package com.erp.management.controller;
import com.erp.management.config.JwtService; import com.erp.management.dto.AuthRequest; import com.erp.management.entity.User; import com.erp.management.repository.UserRepository; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 @PostMapping("/register") ResponseEntity<?> register(@RequestBody AuthRequest r){ if(r.phone==null&&r.email==null) throw new IllegalArgumentException("Phone or email is required"); if((r.phone!=null&&users.existsByPhone(r.phone))||(r.email!=null&&users.existsByEmail(r.email))) return ResponseEntity.badRequest().body(Map.of("message","User with this Phone/Email already exists.")); if(r.name==null||r.password==null) throw new IllegalArgumentException("Name and password are required"); User u=new User();u.name=r.name;u.phone=blankToNull(r.phone);u.email=blankToNull(r.email);u.password=encoder.encode(r.password);u.role=r.role==null?"owner":r.role;u=users.save(u);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("message","User registered successfully!","userId",u.id)); }
 @PostMapping("/login") ResponseEntity<?> login(@RequestBody AuthRequest r){ Optional<User> result=r.phone!=null&&!r.phone.isBlank()?users.findByPhone(r.phone):users.findByEmail(r.email); if(result.isEmpty())return ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of("message","User not found")); User u=result.get();if(!encoder.matches(r.password,u.password))return ResponseEntity.badRequest().body(Map.of("message","Wrong password"));return ResponseEntity.ok(Map.of("token",jwt.createToken(u.id,u.role),"user",Map.of("name",u.name,"role",u.role))); }
 private String blankToNull(String v){return v==null||v.isBlank()?null:v;}
}
